CREATE OR REPLACE FUNCTION public.active_term(_school uuid) RETURNS TABLE(year integer, term integer, start_date date, end_date date) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT coalesce(public.has_perm(_school,'view'),false) THEN RAISE EXCEPTION 'Not permitted'; END IF; RETURN QUERY SELECT t.year,t.term,t.start_date,t.end_date FROM public.school_terms t WHERE t.school_id=_school AND current_date BETWEEN t.start_date AND t.end_date LIMIT 1; IF NOT FOUND THEN RETURN QUERY SELECT s.current_year,s.current_term,NULL::date,NULL::date FROM public.schools s WHERE s.id=_school; END IF; END $$;
REVOKE EXECUTE ON FUNCTION public.active_term(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.active_term(uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.school_subscription_active(_school uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.school_subscriptions sub WHERE sub.school_id=_school AND sub.status='active' AND sub.subscription_ends_at>now() AND (auth.role()='service_role' OR public.is_super_admin() OR EXISTS(SELECT 1 FROM public.school_members m WHERE m.school_id=_school AND m.user_id=auth.uid() AND m.status='active'))) $$;
REVOKE EXECUTE ON FUNCTION public.school_subscription_active(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.school_subscription_active(uuid) TO authenticated,service_role;
CREATE TABLE public.school_receipt_settings(school_id uuid PRIMARY KEY REFERENCES public.schools(id), automatic_numbering boolean NOT NULL DEFAULT false, next_number bigint NOT NULL DEFAULT 1 CHECK(next_number BETWEEN 1 AND 2147483647));
GRANT SELECT ON public.school_receipt_settings TO authenticated;
GRANT ALL ON public.school_receipt_settings TO service_role;
ALTER TABLE public.school_receipt_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY receipt_settings_read ON public.school_receipt_settings FOR SELECT TO authenticated USING(public.has_perm(school_id,'view'));
CREATE OR REPLACE FUNCTION public.save_receipt_settings(_school uuid,_enabled boolean,_next bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT coalesce(public.has_perm(_school,'settings'),false) THEN RAISE EXCEPTION 'Not permitted'; END IF; IF _enabled IS NULL OR _next IS NULL OR _next NOT BETWEEN 1 AND 2147483647 THEN RAISE EXCEPTION 'Enter a receipt number between 1 and 2147483647'; END IF; PERFORM 1 FROM public.schools WHERE id=_school FOR UPDATE; INSERT INTO public.school_receipt_settings(school_id,automatic_numbering,next_number) VALUES(_school,_enabled,_next) ON CONFLICT(school_id) DO UPDATE SET automatic_numbering=excluded.automatic_numbering,next_number=excluded.next_number; INSERT INTO public.audit_logs(school_id,user_id,action,details) VALUES(_school,auth.uid(),'receipt.settings.updated',jsonb_build_object('automatic',_enabled,'next_number',_next)); END $$;
REVOKE EXECUTE ON FUNCTION public.save_receipt_settings(uuid,boolean,bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.save_receipt_settings(uuid,boolean,bigint) TO authenticated;
CREATE OR REPLACE FUNCTION public.assign_school_receipt_number() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cfg public.school_receipt_settings; n bigint; y integer; BEGIN SELECT current_year INTO y FROM public.schools WHERE id=NEW.school_id FOR UPDATE; SELECT * INTO cfg FROM public.school_receipt_settings WHERE school_id=NEW.school_id; IF coalesce(cfg.automatic_numbering,false) THEN n:=cfg.next_number; LOOP IF n>2147483647 THEN RAISE EXCEPTION 'Receipt number limit reached'; END IF; NEW.receipt_number:=n::text; EXIT WHEN NOT EXISTS(SELECT 1 FROM public.payment_receipts r WHERE r.school_id=NEW.school_id AND r.receipt_number=NEW.receipt_number); n:=n+1; END LOOP; UPDATE public.school_receipt_settings SET next_number=n+1 WHERE school_id=NEW.school_id; ELSE SELECT count(*)+1 INTO n FROM public.payment_receipts WHERE school_id=NEW.school_id; LOOP NEW.receipt_number:='RCT-'||y||'-'||lpad(n::text,greatest(6,length(n::text)),'0'); EXIT WHEN NOT EXISTS(SELECT 1 FROM public.payment_receipts r WHERE r.school_id=NEW.school_id AND r.receipt_number=NEW.receipt_number); n:=n+1; END LOOP; END IF; RETURN NEW; END $$;
REVOKE EXECUTE ON FUNCTION public.assign_school_receipt_number() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER assign_receipt_number BEFORE INSERT ON public.payment_receipts FOR EACH ROW EXECUTE FUNCTION public.assign_school_receipt_number();
CREATE POLICY school_logo_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='school-logos' AND EXISTS(SELECT 1 FROM public.schools s WHERE s.id::text=(storage.foldername(name))[1] AND public.has_perm(s.id,'view')));
CREATE POLICY school_logo_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='school-logos' AND EXISTS(SELECT 1 FROM public.schools s WHERE s.id::text=(storage.foldername(name))[1] AND public.has_perm(s.id,'settings')));
ALTER TABLE public.school_sync_devices ADD COLUMN pairing_token_hash text;
COMMENT ON COLUMN public.school_sync_devices.pairing_token_hash IS 'Hash of the secret issued on first pairing, required for unauthenticated device status checks.';